old2=json.loads((ROOT/'instructional_on_ramp/week_01/or_02.json').read_text())
old5=json.loads((ROOT/'instructional_on_ramp/week_01/or_05.json').read_text())
e2={e['key']:e for e in old2['exercises']}
e5={e['key']:e for e in old5['exercises']}
FLIGHT=['jump_reference','jump_short','first_flight']
LANDING_ROUTES=FLIGHT+['grounded_snap','slow_position']
HIP_ROUTES=['bw_reference','bw_low_hold','bw_initial','db_retained','db_low_hold','db_first_setup']

def primary_count(mode,route,cap=None):
    if mode.endswith('_L') and route in FLIGHT:return 0
    n=(1 if mode.startswith('compressed') else 2) if route=='first_flight' else (2 if mode.startswith('compressed') else 3)
    return min(n,cap) if cap else n

def landing(age,mode,key,route,cap=None):
    allowed=not(mode.endswith('_L') and route in FLIGHT)
    n=(1 if key=='P2' else primary_count(mode,route,cap)) if allowed else 0
    actual_route='slow_position' if route=='first_flight' and key=='P2' else route
    if not n:
        d=dose('Unavailable flight route in L — choose an independently eligible grounded route',0,reps=0,tempo_s=0,
               effort='No physical work is assigned on this unavailable route.',rest_s=60)
        d.update(active_s=0,flight_opportunities_per_set=0,landing_foot_contacts_if_bilateral=0,forward_target_m=0,
                 hold_s_per_attempt=0,execution_segments=[])
        return d
    if actual_route in ['jump_reference','jump_short']:
        target=0.1 if key=='P2' or actual_route=='jump_short' else 0.2
        variant='Low-Amplitude Forward Jump to Stick — retained bilateral terminal stick'
        effort=f'Bodyweight, easy low-amplitude intent about 3/10; nominal {target:.2f} m forward target only if it matches the actual eligible route. Retain relaxed-arm start/small natural swing, surface and comfortable finish. No distance contest.'
        segments=[('small_dip_takeoff_flight_landing',2),('terminal_hold',2),('stand_same_bay_reset',4)]
        flight=1
    elif actual_route=='first_flight':
        target=0
        variant='First Bilateral Flight and Hold — proposed in-place teaching variation'
        effort='Bodyweight; one small, gentle vertical takeoff at easy teaching intent about 2–3/10. Use a shallow continuous countermovement and small natural arm swing from beside the trunk. No minimum height, distance score, box, drop, repeated bounce or maximal intent.'
        segments=[('shallow_countermovement_single_takeoff_landing',2),('terminal_hold',2),('stand_same_bay_reset',4)]
        flight=1
    elif actual_route=='grounded_snap':
        target=0;flight=0
        variant='Snap-Down to Stick — bilateral tall-reach stick, continuously grounded'
        effort='Bodyweight, controlled rapid grounded descent; comfortable tall reach and arm drive down, 1 s descent, 2 s hold, 5 s stand/reset. No takeoff. Requires the actual rapid grounded action and reach to be eligible.'
        segments=[('grounded_descent',1),('terminal_hold',2),('stand_reset',5)]
    else:
        target=0;flight=0
        variant='Slow Grounded Landing-Position Squat — declared bodyweight teaching adaptation'
        effort='Bodyweight, easy 2/10 and at least 5 good reps in reserve; 3 s lower into a comfortable partial athletic position, 2 s hold, 1 s stand, 2 s reset. Feet remain grounded; arms reach comfortably forward for balance.'
        segments=[('comfortable_grounded_lower',3),('terminal_hold',2),('stand',1),('reset',2)]
    d=dose(variant,n,reps=1,tempo_s=8,effort=effort,rest_s=60,
           notes='One complete counted opportunity per set. The action/hold/reset phases total 8 s; this is a logistics envelope, not slowed flight or a forced cadence. Count faults and an attempted jump that does not leave the ground; actual successful flight and contacts remain observations. No replacement attempt.')
    d.update(active_s=8,flight_opportunities_per_set=flight,landing_foot_contacts_if_bilateral=2*flight,
             forward_target_m=target,hold_s_per_attempt=2,execution_segments=[{'name':n,'seconds':v} for n,v in segments])
    return d

def hip(age,mode,route,rep_cap=None):
    light=mode.endswith('_L');young=age=='9-11';compressed=mode.startswith('compressed')
    db=route.startswith('db_')
    if db and light:
        return dose('Loaded hinge unavailable in L — select the explicit unloaded route',0,reps=0,tempo_s=0,
                    effort='No loaded work assigned.',rest_s=90)
    if route=='bw_initial':n=2
    elif route in ['bw_low_hold','db_low_hold'] or light:n=2 if young else 3
    elif route=='db_first_setup' and compressed:n=2
    else:n=3 if young else 4
    if rep_cap is not None:
        assert route=='db_first_setup' and rep_cap in [1,2,3]
        n=min(n,rep_cap)
    handling=20 if route=='db_first_setup' else 10 if db else 5
    if db:
        variant='Romanian Deadlift — dumbbell-standard-tempo, TWO dumbbells'
        effort=('First two-dumbbell instructional set: choose an actually manageable light pair from verified stock; no age-wide kg prescription. The unloaded hinge must already be controlled. Observe grip/pickup before the first loaded rep; about 5 or more good reps in reserve by coach judgment. ' if route=='db_first_setup' else
                'Retain the actual familiar pair of loads and owned range; at least 5 good reps in reserve. This is a small supporting/learning dose, not a load test. ')+ 'Lower 3 s and stand 1 s with soft knees. Record kg PER dumbbell, total kg and actual support/range. No load increase within this set.'
    else:
        variant='Bodyweight Hip Hinge Good Morning — arms crossed at chest'
        effort='Bodyweight only, 3 s hips back / 1 s stand, soft knees, comfortable owned range, at least 5 good reps in reserve. '+('One small taught set where history is unknown; do not claim an invented previous dose.' if route=='bw_initial' else 'Retain the actual compatible setup and recent repetition dose; reference D is not an automatic increase.')
    d=dose(variant,1,reps=n,tempo_s=4,effort=effort,rest_s=90 if db else 60,handling_s=handling,
           notes='One set only. Prior two sets are deliberately reduced; a more recent one-set or smaller-repetition record is not overwritten. If handling or execution is unsuitable, count the partial action and end the set; do not add a replacement trial/set.')
    d.update(implements=2 if db else 0,load_kg_each_actual=None,
             handling_segments=([{'name':'paired_implement_pickup','seconds':7},{'name':'top_stand_grip_setup_observation','seconds':3},{'name':'controlled_setdown','seconds':6},{'name':'clear_reset','seconds':4}] if route=='db_first_setup' else
               [{'name':'familiar_pickup','seconds':4},{'name':'familiar_setdown','seconds':4},{'name':'clear_reset','seconds':2}] if db else [{'name':'setup_exit','seconds':5}]))
    if rep_cap is not None:
        d['first_setup_repetition_cap']=rep_cap
        d['notes']+=' This explicit first-implement count hold retains the full 20 s handling and first-setup gates; it does not use familiar-DB handling. Choose no more than the actual recent compatible repetition dose. A ceiling never adds repetitions.'
    return d

